package com.portfolio.features.portfolio.service;
import com.portfolio.common.exception.NotFoundException; import com.portfolio.features.portfolio.entity.Portfolio; import com.portfolio.features.portfolio.repository.PortfolioRepository; import com.portfolio.features.user.entity.AppUser; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class PortfolioAccessService { private final PortfolioRepository portfolios; public Portfolio mine(AppUser user) { return portfolios.findByUserId(user.getId()).orElseThrow(() -> new NotFoundException("Portfolio not found.")); } public Portfolio owned(AppUser user, java.util.UUID id) { Portfolio portfolio = portfolios.findById(id).orElseThrow(() -> new NotFoundException("Portfolio not found.")); if (!portfolio.getUser().getId().equals(user.getId())) throw new NotFoundException("Portfolio not found."); return portfolio; } }
